using System.Text.Json;

namespace Hcc.Domain.Compliance;

// SCC tax port (DEC-116): SCC's compliance catalogue `D` verbatim — 12 month pages April–March, 113 cards, 30 obligation keys, every text
// field and each month's control note. Generated by 03 Prototype/tools/scc-tax-catalogue.mjs into SccTaxCatalogue.json (embedded resource;
// a test checks it is byte-identical to the prototype's copy). Built-in cards are read-only (SCC never mutates D).

/// <summary>
/// One card as the calendar shows it: an SCC built-in (<see cref="IsCustom"/> false) or a custom obligation expanded for one month
/// (SCC <c>expandCustom</c>: id "&lt;gid&gt;-&lt;Mon&gt;", never urgent, control-profile overrides).
/// </summary>
public sealed record SccCard(string Id, string Cat, string Name, string Due, bool Urgent, string Freq, string Form, string Who, string What, string Why, string Penalty)
{
    public bool IsCustom { get; init; }

    /// <summary>The custom obligation id (SCC <c>_gid</c>); null for a built-in card.</summary>
    public string? Gid { get; init; }

    public string Responsible { get; init; } = string.Empty;

    public string Reviewer { get; init; } = string.Empty;

    /// <summary>"High" / "Medium" / "Low" override, or empty (automatic).</summary>
    public string Risk { get; init; } = string.Empty;

    /// <summary>Custom internal buffer 0–30 days, or null (automatic: 5 for High risk, else 3).</summary>
    public int? Buffer { get; init; }

    public IReadOnlyList<string> Checklist { get; init; } = [];

    public IReadOnlyList<string> Workflow { get; init; } = [];

    public IReadOnlyList<string> Evidence { get; init; } = [];
}

public sealed record SccMonth(string Note, IReadOnlyList<SccCard> Items);

public static class SccTaxCatalogue
{
    /// <summary>SCC MONTHS (L342): the FY pages.</summary>
    public static readonly IReadOnlyList<string> Months = ["April", "May", "June", "July", "August", "September", "October", "November", "December", "January", "February", "March"];

    private static readonly Lazy<(string Json, IReadOnlyDictionary<string, SccMonth> D)> Data = new(Load);

    /// <summary>The embedded catalogue text exactly as generated (JSON of SCC's D).</summary>
    public static string Json => Data.Value.Json.TrimEnd('\n');

    public static IReadOnlyDictionary<string, SccMonth> D => Data.Value.D;

    private static (string, IReadOnlyDictionary<string, SccMonth>) Load()
    {
        using var stream = typeof(SccTaxCatalogue).Assembly.GetManifestResourceStream("Hcc.Domain.Compliance.SccTaxCatalogue.json")
            ?? throw new InvalidOperationException("The SCC tax catalogue resource is missing.");
        using var reader = new StreamReader(stream);
        var json = reader.ReadToEnd();
        using var doc = JsonDocument.Parse(json);
        var d = new Dictionary<string, SccMonth>(StringComparer.Ordinal);
        foreach (var month in doc.RootElement.EnumerateObject())
        {
            var items = new List<SccCard>();
            foreach (var i in month.Value.GetProperty("items").EnumerateArray())
            {
                string S(string k) => i.TryGetProperty(k, out var v) && v.ValueKind == JsonValueKind.String ? v.GetString()! : string.Empty;
                items.Add(new SccCard(S("id"), S("cat"), S("name"), S("due"), i.TryGetProperty("urgent", out var u) && u.ValueKind == JsonValueKind.True,
                    S("freq"), S("form"), S("who"), S("what"), S("why"), S("penalty")));
            }

            d[month.Name] = new SccMonth(month.Value.GetProperty("note").GetString() ?? string.Empty, items);
        }

        if (!d.Keys.SequenceEqual(Months)) throw new InvalidOperationException("The SCC tax catalogue months are out of order.");
        return (json, d);
    }

    /// <summary>The built-in cards of one page (SCC D[month].items).</summary>
    public static IReadOnlyList<SccCard> BuiltIn(string month) => D.TryGetValue(month, out var m) ? m.Items : [];

    public static string Note(string month) => D.TryGetValue(month, out var m) ? m.Note : string.Empty;

    /// <summary>Every built-in card with its page month, in catalogue order.</summary>
    public static IEnumerable<(string Month, SccCard Card)> All() => Months.SelectMany(m => BuiltIn(m).Select(c => (m, c)));

    /// <summary>The page month of a built-in card id, or null.</summary>
    public static string? BuiltInMonth(string itemId) => Months.FirstOrDefault(m => BuiltIn(m).Any(c => c.Id == itemId));

    /// <summary>SCC builtInObligations (L1489–1498): the unique built-in keys in catalogue order with the category of the first card.</summary>
    public static IReadOnlyList<(string Key, string Cat, string Name)> BuiltInObligations()
    {
        var seen = new HashSet<string>(StringComparer.Ordinal);
        var list = new List<(string, string, string)>();
        foreach (var (_, c) in All())
        {
            var key = SccTaxRules.ObligationKey(c);
            if (key.Length > 0 && seen.Add(key)) list.Add((key, c.Cat, c.Name));
        }

        return list;
    }
}
